# Lanternhold v139: Paladin class, first-purchase bonus, Surge shout-out, Lanternholder gifts, new looks.
# Paste into AWS CloudShell (us-east-1). Needs John's go. Run AFTER v138-hall-of-fame.sh (it creates lanternhold-hof).
# Updates the code of 9 Lambdas from infra/lambda/*.js and infra/ring/index.js, and gives lanternhold-store and
# lanternhold-perks read access to the heroes table (env HEROES) for the shout-out name and gifts.
# Backs up every function to ~/lhbak first and prints the undo commands. Safe to run twice.
set -e
TS=$(date -u +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhv139 && cd ~/lhv139
HT=$(aws dynamodb describe-table --table-name lanternhold-heroes --query Table.TableArn --output text)
UNDO=""
put() { # put <function> <dir>: back up, check the pasted code, zip and update
  F=$1; D=$2
  curl -s -o ~/lhbak/$F-$TS.zip "$(aws lambda get-function --function-name $F --query Code.Location --output text)"
  [ "$(md5sum $D/index.js | cut -c1-32)" = "$3" ] || { echo "$F: the code did not paste cleanly. Stopping; nothing after this changed."; exit 1; }
  rm -f $D.zip && (cd $D && zip -qj ../$D.zip index.js)
  aws lambda update-function-code --function-name $F --zip-file fileb://$D.zip >/dev/null
  aws lambda wait function-updated --function-name $F
  UNDO="$UNDO\naws lambda update-function-code --function-name $F --zip-file fileb://$HOME/lhbak/$F-$TS.zip"
  echo "updated $F"
}
mkdir -p heroes && echo  | base64 -d > heroes/index.js
put lanternhold-heroes heroes b82a13703b7a54b67d30aedd539fd5bc
mkdir -p market && echo  | base64 -d > market/index.js
put lanternhold-market market a726d5911ee0e2ba33e3553522ea267b
mkdir -p mail && echo  | base64 -d > mail/index.js
put lanternhold-mail mail f7477d605c605899dd17ce4300158178
mkdir -p looks && echo  | base64 -d > looks/index.js
put lanternhold-looks looks 452a3f6ce9b1019df17ff1c35ea66b43
mkdir -p store && echo  | base64 -d > store/index.js
put lanternhold-store store 5087b1eb86370d37cb456b1e8289f5d3
mkdir -p perks && echo  | base64 -d > perks/index.js
put lanternhold-perks perks ee647a0f71ddf541b3a53d2bdf2372f3
mkdir -p profile && echo  | base64 -d > profile/index.js
put lanternhold-profile profile c90dd97b867bae00316808c657023202
mkdir -p hof && echo  | base64 -d > hof/index.js
put lanternhold-hof hof fc1f89a82d0624f8aff1403b9e15cec8
mkdir -p ring && echo  | base64 -d > ring/index.js
put lanternhold-arena ring f4e484a4187f6b1a16d1cd01b466653b
# store and perks: add HEROES to their env (keeping every other variable) and let them read hero rows
for F in lanternhold-store lanternhold-perks; do
  ROLE=$(aws lambda get-function-configuration --function-name $F --query Role --output text | awk -F/ '{print $NF}')
  aws iam put-role-policy --role-name "$ROLE" --policy-name lanternhold-v139-heroes --policy-document "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"dynamodb:GetItem\",\"Resource\":\"$HT\"}]}"
  aws lambda get-function-configuration --function-name $F --query Environment > env-$F.json
  python3 -c "import json,sys; e=json.load(open('env-$F.json')) or {}; v=e.get('Variables',{}); v['HEROES']='lanternhold-heroes'; v['STARTER']='d1873d91-0d6c-4311-89af-1125d21a3cf6'; print(json.dumps({'Variables':v}))" > env2-$F.json
  aws lambda update-function-configuration --function-name $F --environment file://env2-$F.json >/dev/null
  aws lambda wait function-updated --function-name $F
  echo "env HEROES + STARTER set on $F"
done
# smoke tests: public routes answer, signed-in routes still say 401 without a token
curl -s -o /dev/null -w "GET /surge: %{http_code} (200 is right)\n" https://nyu3u8gc73.execute-api.us-east-1.amazonaws.com/surge
curl -s -o /dev/null -w "GET /arena without sign-in: %{http_code} (401 is right)\n" https://nyu3u8gc73.execute-api.us-east-1.amazonaws.com/arena
curl -s -o /dev/null -w "GET /wardrobe without sign-in: %{http_code} (401 is right)\n" https://nyu3u8gc73.execute-api.us-east-1.amazonaws.com/wardrobe
echo "done. Backups in ~/lhbak/*-$TS.zip. Undo:"; echo -e "$UNDO"
